template:
fn longest⟦generics⟧(a: ⟦param_ty⟧, b: ⟦param_ty⟧) -> ⟦ret_ty⟧ {
    if a.len() > b.len() { a } else { b }
}

fn main() {
    let one = String::from("ferris");
    let two = String::from("rustchap");
    println!("{}", longest(&one, &two));
}

tests:
#[test]
fn picks_longer() {
    let a = String::from("hi");
    let b = String::from("there");
    assert_eq!(longest(&a, &b), "there");
}
